#!/bin/bash
# Module 13 option (a): in-port cone injector case (already generated by make_port_case.py), 2 ranks, nice 19.
cd "$(dirname "$0")/.." || exit 1
C=${1:-M13-US20C-coarse}
log() { echo "$(date '+%F %T %Z') $*" >> port13/progress.txt; }
rss() { ps -eo rss,comm | awk '$2=="reactingParcelFo"||$2=="reactingParcelFoam"||$2=="snappyHexMesh"{t+=$1} END{print int(t/1024)}'; }
log "$C start (option a cone injector)"
t0=$(date +%s)
( cd runs/$C && nice -n 19 ./Allrun > allrun.nohup 2>&1 ) &
pid=$!; peak=0
while kill -0 $pid 2>/dev/null; do s=$(rss); [ "$s" -gt "$peak" ] && { peak=$s; echo $peak > runs/$C/peak_rss_mb.partial; }; sleep 5; done
wait $pid; rc=$?
echo $peak > runs/$C/peak_rss_mb.txt
log "$C done rc=$rc runtime_s $(( $(date +%s)-t0 )) peak RSS ${peak} MB ($(tail -1 runs/$C/log.Allrun))"
python3 port13/post_m13.py $C >> port13/progress.txt 2>&1 || log "$C post FAILED"
